Import ListNotations. Import KXS.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Set Warnings "-notation-for-abbreviation".
Notation amem := (word -> option byte).

(* [comment removed for export] *)
Definition w4s_src_ctx (RNG : footprint) (mm : amem) (SS n SBL SBH : Z) : Prop :=
  mem_inv asegs mm
  /\ (exists sbuf, bytes_at asegs mm SS sbuf /\ Z.of_nat (length sbuf) = n)
  /\ unpoisoned mm SBL SBH /\ SBL <= SS /\ SS + n <= SBH /\ SBL mod 8 = 0
  /\ rng RNG SS n /\ rng RNG (shad SBL) (shlen (SBH - SBL + 7)) /\ rng_aimg RNG
  /\ 0x60d000 <= SS /\ SS + n <= 2^47 /\ 0x60d000 <= SBL /\ SBH <= 2^47.

Ltac w4s_src_intro C :=
  let MI := fresh "MI" in let sbuf := fresh "sbuf" in let SB := fresh "SB" in let SL := fresh "SL" in
  destruct C as (MI & (sbuf & SB & SL) & ?US & ?US1 & ?US2 & ?A8 & ?WS & ?WSS & ?WI & ?R1 & ?R2 & ?R3 & ?R4).

Definition w4s_B1_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x5 x6 x7 x8 x9 x10 x11 x13 x14 x15 x16 x17 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word)
         (P SS n SBL SBH E : Z) (jd : word),
    w4s_src_ctx RNG mm SS n SBL SBH ->
    ztab_fact asegs mm (E - 1) 1 1 [(0, 1, 255)] ->
    SS + 8 <= E <= SS + n ->
    rw_cells asegs mm (P + 32) [C8 jd] -> rw_cells asegs mm (P + 136) [C8 (Z_to_bv 64 2147450880)] ->
    rng RNG P 496 -> 0x10007fff8000 <= P -> P + 496 <= 2^47 -> SS + n <= P ->
    (forall (r : Z) (t0 a6 a7 : word) (mm' : amem), 1 <= r <= 255 ->
       munch [(P + 32, P + 40)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' ->
       rw_cells asegs mm' (P + 32) [C8 x6] ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp t0 x6 x7 x8 x9 x10 (Z_to_bv 64 r) (Z_to_bv 64 (E + -1))
                                 x13 x14 x15 a6 a7 (Z_to_bv 64 E) x19 x20 x21 x22 x23 x24 x25 (Z_to_bv 64 (E + -8)) x27
                                 x28 x29 x30 x31)
                            F (Z_to_bv 64 0x902c0) fc None mm' (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 x8 x9 x10 x11 (Z_to_bv 64 (E + -1)) x13 x14 x15 x16 x17
                             (Z_to_bv 64 E) x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
                        F (Z_to_bv 64 0x90274) fc None mm (seg_rom asegs)).

