(* [comment removed for export] *)
Definition w4s_S1_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x5 x6 x7 x8 x9 x10 x11 x13 x14 x15 x17 x19 x21 x22 x23 x24 x25 x26 x27 x28 x29 x31 : word)
         (P SS n SBL SBH l lo hi : Z),
    w4s_src_ctx RNG mm SS n SBL SBH ->
    ztab_fact asegs mm (SS + 6 + l - 1) 1 1 [(0, lo, hi)] -> (lo = 1 /\ hi = 255 \/ lo = 0 /\ hi = 0) ->
    1 <= l <= 7 -> 6 + l <= n ->
    rw_cells asegs mm (P + 136) [C8 (Z_to_bv 64 2147450880)] ->
    rng RNG P 496 -> 0x10007fff8000 <= P -> P + 496 <= 2^47 -> SS + n <= P ->
    (forall (r : Z) (t0 c a7 : word), 1 <= r <= 255 -> lo = 1 ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp t0 x6 c x8 x9 x10 (Z_to_bv 64 r) (Z_to_bv 64 (SS + 6 + l + -1)) x13
                                 x14 x15 (Z_to_bv 64 l) a7 (Z_to_bv 64 (SS + 6 + l)) x19 (Z_to_bv 64 (SS + 6)) x21 x22 x23 x24 x25
                                 x26 x27 x28 x29 (Z_to_bv 64 SS) x31)
                            F (Z_to_bv 64 0x904f4) fc None mm (seg_rom asegs))) ->
    (forall (t0 c a1 a7 : word), lo = 0 ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp t0 x6 c x8 x9 x10 a1 (Z_to_bv 64 (SS + 6 + l + -1)) x13
                                 x14 x15 (Z_to_bv 64 l) a7 (Z_to_bv 64 (SS + 6 + l)) x19 (Z_to_bv 64 (SS + 6)) x21 x22 x23 x24 x25
                                 x26 x27 x28 x29 (Z_to_bv 64 SS) x31)
                            F (Z_to_bv 64 0x91bc0) fc None mm (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 x8 x9 x10 x11 (Z_to_bv 64 (SS + 6 + l + -1)) x13
                             x14 x15 (Z_to_bv 64 l) x17 (Z_to_bv 64 (SS + 6 + l)) x19 (Z_to_bv 64 (SS + 6)) x21 x22 x23 x24 x25
                             x26 x27 x28 x29 (Z_to_bv 64 SS) x31)
                        F (Z_to_bv 64 0x9039c) fc None mm (seg_rom asegs)).

Ltac w4s_small_post K K0 :=
  kx_post_regs_keep;
  lazymatch goal with |- context [mem_denot ?E' ?m []] => change (mem_denot E' m []) with m end;
  lazymatch goal with
  | |- evtF _ _ _ (MS _ _ (Z_to_bv 64 0x91bf0) _ _ _ _) => eapply K0; reflexivity
  | |- evtF _ _ _ (MS (mkR _ _ _ _ _ _ _ _ _ _ (ev ?E' ?j) _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _) _ _ _ _ _ _) =>
      let H := fresh "H" in kx_range (EVar j) H;
      replace (ev E' j) with (Z_to_bv 64 (bv_unsigned (ev E' j))) by (apply Z_to_bv_bv_unsigned);
      eapply (K (bv_unsigned (ev E' j))); [ exact H | reflexivity ]
  end.

